#!/usr/bin/env node
/* Differential harness: reference executable vs the Node port. */
import { execFileSync, spawnSync } from 'node:child_process';

const EXE = '/workspace/dataset/test4_executable';
const JS = '/output/test4.mjs';

function run(cmd, args, argv, cwd, env) {
  const r = spawnSync(cmd, [...args, ...argv], {
    cwd, encoding: 'buffer', env: { ...process.env, ...env },
  });
  return {
    code: r.status,
    out: r.stdout.toString('utf8'),
    err: r.stderr.toString('utf8'),
  };
}

// Normalize the two legitimately-variable pieces of stderr:
//   - the PYI tag carries the pid
//   - argparse's prog name comes from argv[0]/argv[1]
function norm(s) {
  return s
    .replace(/\[PYI-\d+:ERROR\]/g, '[PYI-PID:ERROR]')
    .replace(/test4_executable|test4\.mjs/g, 'PROG');
}

const CASES = JSON.parse(process.argv[2]);
const cwd = process.argv[3] || '/workspace/dataset';

let pass = 0;
const fails = [];
for (const argv of CASES) {
  const a = run(EXE, [], argv, cwd);
  const b = run('node', [JS], argv, cwd);
  const problems = [];
  if (a.code !== b.code) problems.push(`exit ${a.code} vs ${b.code}`);
  if (norm(a.out) !== norm(b.out)) problems.push(`stdout ${JSON.stringify(norm(a.out))} vs ${JSON.stringify(norm(b.out))}`);
  if (norm(a.err) !== norm(b.err)) {
    problems.push(`stderr\n  py=${JSON.stringify(norm(a.err))}\n  js=${JSON.stringify(norm(b.err))}`);
  }
  if (problems.length === 0) pass += 1;
  else fails.push({ argv, problems });
}

console.log(`cwd=${cwd}  pass ${pass}/${CASES.length}`);
for (const f of fails) {
  console.log(`FAIL ${JSON.stringify(f.argv)}`);
  for (const p of f.problems) console.log(`   ${p}`);
}
process.exitCode = fails.length ? 1 : 0;

/**
 * Node.js port of `test4.py`:
 *
 *     import argparse
 *     import schedule
 *
 *     parser = argparse.ArgumentParser()
 *     parser.add_argument('--a', type=str, required=True)
 *     parser.add_argument('--b', type=str, required=True)
 *     parser.add_argument('--c', type=str, required=True)
 *     args = parser.parse_args()
 *
 *     job = schedule.every().monday.at(args.a)  # 创建每周一特定时间作业
 *     print(job)
 *
 * `--b` and `--c` are required but unused, exactly as in the original — only
 * `--a` reaches `Job.at()`.
 *
 * Exit codes match the reference build: 0 on success (and for `--help`),
 * 2 for an argparse failure, 1 for an unhandled exception out of `at()`.
 */
import { ArgumentParser, SystemExit, str } from './lib/argparse/index.mjs';
import schedule from './lib/schedule/index.mjs';
import { PyError } from './lib/py/errors.mjs';
import { frame, printTraceback } from './lib/runtime/traceback.mjs';

/** Byte columns of `schedule.every().monday.at(args.a)` within source line 10. */
const AT_CALL_COLNO = 6;
const AT_CALL_END_COLNO = 40;

function main() {
  const parser = new ArgumentParser();
  parser.addArgument('--a', { type: str, required: true });
  parser.addArgument('--b', { type: str, required: true });
  parser.addArgument('--c', { type: str, required: true });
  const args = parser.parseArgs();

  const job = schedule.every().monday.at(args.a);
  console.log(String(job));
}

try {
  main();
} catch (err) {
  if (err instanceof SystemExit) {
    // argparse asked to terminate: `--help` exits 0, a usage error exits 2.
    process.exitCode = err.code;
  } else if (err instanceof PyError) {
    // Unhandled Python-level exception, reported the way the frozen build does.
    printTraceback(
      [
        frame('test4.py', 10, '<module>', AT_CALL_COLNO, AT_CALL_END_COLNO),
        frame('schedule/__init__.py', err.pyLineno ?? 0, err.pyFunction ?? 'at'),
      ],
      err.pyName,
      err.message,
      'test4',
    );
    process.exitCode = 1;
  } else {
    throw err;
  }
}
