/**
 * A focused port of `argparse.ArgumentParser`.
 *
 * The parsing algorithm follows CPython's `_parse_known_args` closely, because
 * the observable edge cases fall out of its internals rather than from any
 * simpler model:
 *
 *   - Each argv entry is first classified into a pattern string of `O`
 *     (looks like an option), `A` (looks like a value) and `-` (the `--`
 *     separator); everything after `--` is forced to `A`.
 *   - An option taking one value matches the pattern `(A)` — with the `-`
 *     characters stripped precisely because `--` may not be swallowed as a
 *     value. That is why `--b -- --c y` reports `argument --b: expected one
 *     argument` rather than treating `--` as `--b`'s value.
 *   - Anything that starts with `-`, is not a known option and looks like a
 *     negative number is reclassified as a value, so `--a -5` sets `a="-5"`.
 *   - The missing-required check lives inside `parse_known_args`, while the
 *     unrecognized-argument check happens afterwards in `parse_args`. Hence a
 *     command line with both faults reports the missing options first.
 */
import path from 'node:path';

import { pyMatch } from '../py/regex.mjs';
import { pyRepr } from '../py/text.mjs';
import { ArgumentError, SystemExit } from './errors.mjs';
import { StoreAction, HelpAction } from './actions.mjs';
import { HelpFormatter } from './help-formatter.mjs';

/** `_get_action_name` — how an action is referred to in error messages. */
function actionName(action) {
  if (action === null || action === undefined) return null;
  if (action.optionStrings.length > 0) return action.optionStrings.join('/');
  if (action.metavar !== null && action.metavar !== undefined) return action.metavar;
  if (action.dest !== null && action.dest !== undefined) return action.dest;
  return null;
}

export class ArgumentParser {
  constructor({
    prog = null,
    usage = null,
    description = null,
    epilog = null,
    prefixChars = '-',
    addHelp = true,
    allowAbbrev = true,
  } = {}) {
    // argparse: os.path.basename(sys.argv[0]).
    this.prog = prog ?? path.basename(process.argv[1] ?? 'program');
    this.usage = usage;
    this.description = description;
    this.epilog = epilog;
    this.prefixChars = prefixChars;
    this.allowAbbrev = allowAbbrev;

    this.actions = [];
    this.optionStringActions = new Map();
    /** Declared positional actions; this parser has none. */
    this.positionalActions = [];

    // Groups exist so the help output carries argparse's section headings.
    this.actionGroups = [
      { title: 'positional arguments', actions: this.positionalActions },
      { title: 'options', actions: [] },
    ];

    if (addHelp) {
      this.addArgument(['-h', '--help'], {
        action: 'help',
        help: 'show this help message and exit',
      });
    }
  }

  // --- declaration ---------------------------------------------------------

  /**
   * `add_argument`. Only the keywords `test4.py` uses are honoured; `dest` is
   * derived from the first long option with its prefix characters stripped, and
   * the metavar defaults to the uppercased dest.
   */
  addArgument(names, {
    action = 'store',
    nargs = null,
    type = null,
    required = false,
    help = null,
    metavar = null,
    defaultValue = null,
    choices = null,
  } = {}) {
    const optionStrings = Array.isArray(names) ? names : [names];
    const longOption = optionStrings.find(
      s => s.length > 1 && this.prefixChars.includes(s[0]) && this.prefixChars.includes(s[1]),
    );
    const source = longOption ?? optionStrings[0];
    const dest = source.replace(new RegExp(`^[${this.prefixChars}]+`, 'u'), '')
      .replace(/-/gu, '_');

    const created = action === 'help'
      ? new HelpAction({ optionStrings, dest, help })
      : new StoreAction({
        optionStrings, dest, nargs, type, required, help, metavar, defaultValue, choices,
      });

    this.actions.push(created);
    this.actionGroups[1].actions.push(created);
    for (const optionString of optionStrings) {
      this.optionStringActions.set(optionString, created);
    }
    return created;
  }

  // --- help / usage --------------------------------------------------------

  getFormatter() {
    return new HelpFormatter({ prog: this.prog });
  }

  formatUsage() {
    const formatter = this.getFormatter();
    formatter.addUsage(this.usage, this.actions);
    return formatter.formatHelp();
  }

  formatHelp() {
    const formatter = this.getFormatter();
    formatter.addUsage(this.usage, this.actions);
    formatter.addText(this.description);
    for (const group of this.actionGroups) {
      formatter.startSection(group.title);
      formatter.addArguments(group.actions);
      formatter.endSection();
    }
    formatter.addText(this.epilog);
    return formatter.formatHelp();
  }

  printUsage(stream = process.stdout) {
    stream.write(this.formatUsage());
  }

  printHelp(stream = process.stdout) {
    stream.write(this.formatHelp());
  }

  /** `parser.error()` — usage to stderr, then `prog: error: msg`, exit 2. */
  error(message) {
    this.printUsage(process.stderr);
    process.stderr.write(`${this.prog}: error: ${message}\n`);
    throw new SystemExit(2);
  }

  // --- classification ------------------------------------------------------

  /** argparse's `_negative_number_matcher`. */
  looksLikeNegativeNumber(argString) {
    return pyMatch(String.raw`^-\d+$|^-\d*\.\d+$`, argString) !== null;
  }

  /** True when any declared option itself looks like a negative number. */
  get hasNegativeNumberOptionals() {
    return [...this.optionStringActions.keys()].some(
      s => this.looksLikeNegativeNumber(s),
    );
  }

  /** `_get_option_tuples` — abbreviation and `-xVALUE` resolution. */
  getOptionTuples(argString) {
    const result = [];
    const chars = this.prefixChars;

    if (chars.includes(argString[0]) && chars.includes(argString[1])) {
      if (this.allowAbbrev) {
        let optionPrefix = argString;
        let explicitArg = null;
        const eq = argString.indexOf('=');
        if (eq !== -1) {
          optionPrefix = argString.slice(0, eq);
          explicitArg = argString.slice(eq + 1);
        }
        for (const [optionString, action] of this.optionStringActions) {
          if (optionString.startsWith(optionPrefix)) {
            result.push([action, optionString, explicitArg]);
          }
        }
      }
    } else if (chars.includes(argString[0]) && !chars.includes(argString[1])) {
      const optionPrefix = argString;
      const shortOptionPrefix = argString.slice(0, 2);
      const shortExplicitArg = argString.slice(2);
      for (const [optionString, action] of this.optionStringActions) {
        if (optionString === shortOptionPrefix) {
          result.push([action, optionString, shortExplicitArg]);
        } else if (optionString.startsWith(optionPrefix)) {
          result.push([action, optionString, null]);
        }
      }
    } else {
      this.error(`unexpected option string: ${argString}`);
    }
    return result;
  }

  /**
   * `_parse_optional` — decide whether `argString` is an option.
   *
   * Returns `null` when the string is a value, or `[action, optionString,
   * explicitArg]` when it is an option. A returned `action` of `null` means
   * "looks like an option but is not one of ours", which becomes an
   * unrecognized-argument extra.
   */
  parseOptional(argString) {
    if (!argString) return null;
    if (!this.prefixChars.includes(argString[0])) return null;
    if (this.optionStringActions.has(argString)) {
      return [this.optionStringActions.get(argString), argString, null];
    }
    if (argString.length === 1) return null;

    const eq = argString.indexOf('=');
    if (eq !== -1) {
      const optionString = argString.slice(0, eq);
      const explicitArg = argString.slice(eq + 1);
      if (this.optionStringActions.has(optionString)) {
        return [this.optionStringActions.get(optionString), optionString, explicitArg];
      }
    }

    const optionTuples = this.getOptionTuples(argString);
    if (optionTuples.length > 1) {
      const matches = optionTuples.map(([, optionString]) => optionString).join(', ');
      this.error(`ambiguous option: ${argString} could match ${matches}`);
    } else if (optionTuples.length === 1) {
      return optionTuples[0];
    }

    if (this.looksLikeNegativeNumber(argString)) {
      if (!this.hasNegativeNumberOptionals) return null;
    }
    if (argString.includes(' ')) return null;

    return [null, argString, null];
  }

  /** `_get_nargs_pattern`, including the `--`-stripping for optionals. */
  nargsPattern(action) {
    const { nargs } = action;
    let pattern;
    if (nargs === null || nargs === undefined) pattern = '(-*A-*)';
    else if (nargs === '?') pattern = '(-*A?-*)';
    else if (nargs === '*') pattern = '(-*[A-]*)';
    else if (nargs === '+') pattern = '(-*A[A-]*)';
    else if (nargs === '...') pattern = '([-AO]*)';
    else pattern = `(-*${Array.from({ length: nargs }, () => 'A').join('-*')}-*)`;

    if (action.optionStrings.length > 0) {
      pattern = pattern.split('-*').join('').split('-').join('');
    }
    return pattern;
  }

  /** `_match_argument` — how many argv entries this action consumes. */
  matchArgument(action, argStringsPattern) {
    const match = new RegExp(`^${this.nargsPattern(action)}`, 'u').exec(argStringsPattern);
    if (match === null) {
      const messages = {
        null: 'expected one argument',
        '?': 'expected at most one argument',
        '+': 'expected at least one argument',
      };
      const key = action.nargs === null || action.nargs === undefined ? 'null' : action.nargs;
      const message = messages[key]
        ?? `expected ${action.nargs} argument${action.nargs === 1 ? '' : 's'}`;
      throw new ArgumentError(actionName(action), message);
    }
    return match[1].length;
  }

  // --- value conversion ----------------------------------------------------

  getValue(action, argString) {
    if (typeof action.type === 'function') {
      try {
        return action.type(argString);
      } catch (err) {
        throw new ArgumentError(
          actionName(action),
          `invalid ${action.type.name || pyRepr(action.type)} value: ${pyRepr(argString)}`,
        );
      }
    }
    return argString;
  }

  checkValue(action, value) {
    if (action.choices !== null && action.choices !== undefined
      && !action.choices.includes(value)) {
      throw new ArgumentError(
        actionName(action),
        `invalid choice: ${pyRepr(value)} (choose from `
        + `${action.choices.map(c => pyRepr(c)).join(', ')})`,
      );
    }
  }

  /**
   * `_get_values`.
   *
   * The leading `--` is stripped only for *positionals*. That scoping is what
   * makes `--a=--` store the two-character string `"--"` and fall through to
   * `at()`'s format error, rather than yielding an empty list. Since this
   * parser declares no positionals, the removal never actually fires.
   */
  getValues(action, argStrings) {
    let strings = argStrings;
    if (action.optionStrings.length === 0 && action.nargs !== '...') {
      const index = strings.indexOf('--');
      if (index !== -1) {
        strings = [...strings.slice(0, index), ...strings.slice(index + 1)];
      }
    }
    if (strings.length === 1 && (action.nargs === null || action.nargs === '?')) {
      const value = this.getValue(action, strings[0]);
      this.checkValue(action, value);
      return value;
    }
    const values = strings.map(s => this.getValue(action, s));
    values.forEach(v => this.checkValue(action, v));
    return values;
  }

  // --- parsing -------------------------------------------------------------

  parseArgs(args = null) {
    const [namespace, extras] = this.parseKnownArgs(args);
    if (extras.length > 0) {
      this.error(`unrecognized arguments: ${extras.join(' ')}`);
    }
    return namespace;
  }

  parseKnownArgs(args = null) {
    const argStrings = args ?? process.argv.slice(2);
    const namespace = {};
    for (const action of this.actions) {
      if (!(action.dest in namespace)) namespace[action.dest] = action.defaultValue;
    }

    try {
      return this.parseKnownArgsInner(argStrings, namespace);
    } catch (err) {
      if (err instanceof ArgumentError) {
        this.error(err.message);
      }
      throw err;
    }
  }

  parseKnownArgsInner(argStrings, namespace) {
    // Classify every argv entry, forcing everything after `--` to be a value.
    const optionStringIndices = new Map();
    const patternParts = [];
    for (let i = 0; i < argStrings.length; i += 1) {
      if (argStrings[i] === '--') {
        patternParts.push('-');
        for (let j = i + 1; j < argStrings.length; j += 1) patternParts.push('A');
        break;
      }
      const optionTuple = this.parseOptional(argStrings[i]);
      if (optionTuple === null) {
        patternParts.push('A');
      } else {
        optionStringIndices.set(i, optionTuple);
        patternParts.push('O');
      }
    }
    const argStringsPattern = patternParts.join('');

    const seenActions = new Set();
    const extras = [];
    /** Positionals still awaiting values; empty for this parser. */
    const positionals = [...this.positionalActions];

    const takeAction = (action, argumentStrings, optionString = null) => {
      seenActions.add(action);
      const argumentValues = this.getValues(action, argumentStrings);
      action.call(this, namespace, argumentValues, optionString);
    };

    const consumeOptional = startIndex => {
      let [action, optionString, explicitArg] = optionStringIndices.get(startIndex);
      const actionTuples = [];
      let stop = startIndex;

      for (;;) {
        if (action === null) {
          extras.push(argStrings[startIndex]);
          return startIndex + 1;
        }
        if (explicitArg !== null && explicitArg !== undefined) {
          const argCount = this.matchArgument(action, 'A');
          if (argCount === 0 && !this.prefixChars.includes(optionString[1])
            && explicitArg !== '') {
            // `-xyz` where `-x` takes no value: peel off `-y` and continue.
            actionTuples.push([action, [], optionString]);
            const char = optionString[0];
            optionString = char + explicitArg[0];
            const newExplicitArg = explicitArg.slice(1) || null;
            if (this.optionStringActions.has(optionString)) {
              action = this.optionStringActions.get(optionString);
              explicitArg = newExplicitArg;
            } else {
              throw new ArgumentError(
                actionName(action), `ignored explicit argument ${pyRepr(explicitArg)}`,
              );
            }
          } else if (argCount === 1) {
            stop = startIndex + 1;
            actionTuples.push([action, [explicitArg], optionString]);
            break;
          } else {
            throw new ArgumentError(
              actionName(action), `ignored explicit argument ${pyRepr(explicitArg)}`,
            );
          }
        } else {
          const start = startIndex + 1;
          const argCount = this.matchArgument(action, argStringsPattern.slice(start));
          stop = start + argCount;
          actionTuples.push([action, argStrings.slice(start, stop), optionString]);
          break;
        }
      }

      for (const [a, values, optString] of actionTuples) {
        takeAction(a, values, optString);
      }
      return stop;
    };

    const consumePositionals = startIndex => {
      // This parser declares no positionals, so nothing is ever consumed here
      // and every leftover argv entry becomes an unrecognized extra.
      let index = startIndex;
      const counts = [];
      for (const action of positionals) {
        const count = this.matchArgument(action, argStringsPattern.slice(index));
        counts.push(count);
        takeAction(action, argStrings.slice(index, index + count));
        index += count;
      }
      positionals.splice(0, counts.length);
      return index;
    };

    let startIndex = 0;
    const maxOptionStringIndex = optionStringIndices.size > 0
      ? Math.max(...optionStringIndices.keys())
      : -1;

    while (startIndex <= maxOptionStringIndex) {
      const nextOptionStringIndex = Math.min(
        ...[...optionStringIndices.keys()].filter(index => index >= startIndex),
      );
      if (startIndex !== nextOptionStringIndex) {
        const positionalsEndIndex = consumePositionals(startIndex);
        if (positionalsEndIndex > startIndex) {
          startIndex = positionalsEndIndex;
          continue;
        }
        startIndex = positionalsEndIndex;
      }
      if (startIndex !== nextOptionStringIndex) {
        extras.push(...argStrings.slice(startIndex, nextOptionStringIndex));
        startIndex = nextOptionStringIndex;
      }
      startIndex = consumeOptional(startIndex);
    }

    const stopIndex = consumePositionals(startIndex);
    extras.push(...argStrings.slice(stopIndex));

    const requiredActions = [];
    for (const action of this.actions) {
      if (!seenActions.has(action) && action.required) {
        requiredActions.push(actionName(action));
      }
    }
    if (requiredActions.length > 0) {
      this.error(`the following arguments are required: ${requiredActions.join(', ')}`);
    }

    return [namespace, extras];
  }
}
